class Solution:
    def getXORSum(self, arr1: List[int], arr2: List[int]) -> int:
        res = 0
        for b in range(30):
            c1 = sum((x >> b) & 1 for x in arr1)
            c2 = sum((x >> b) & 1 for x in arr2)
            if (c1 * c2) % 2 == 1:
                res |= 1 << b
        return res

